/* AE's NEW MODES preset gametypes, pure (no engine): the table (generated by tools/ae_h2_presets_gen.py from the
second-generation game's preset list) and its lookups. ae_h2_presets.c puts a preset into a game variant. Each
preset is its engine's builder plus these values and the AE block (ae_variant_ext_rules.h). */
#ifndef AE_H2_PRESETS_RULES_H
#define AE_H2_PRESETS_RULES_H

#include <stddef.h>
#include "ae_variant_ext_rules.h"

enum
{
	AE_H2_ENGINE_SLAYER = 0, AE_H2_ENGINE_ODDBALL, AE_H2_ENGINE_KING, AE_H2_ENGINE_JUGGERNAUT, AE_H2_ENGINE_CTF,
	AE_H2_ENGINE_BOMB, AE_H2_ENGINE_TERRITORIES,
	AE_H2_PRESET_COUNT = 42
};

/* what a preset changes of its base seed (struct ae_h2_preset's twist): the rest is the base seed's own */
enum
{
	AE_H2_TWIST_SCORE = 1 << 0, AE_H2_TWIST_LIVES = 1 << 1, AE_H2_TWIST_RESPAWN = 1 << 2, AE_H2_TWIST_SUICIDE = 1 << 3,
	AE_H2_TWIST_BETRAYAL = 1 << 4, AE_H2_TWIST_SHIELDS = 1 << 5, AE_H2_TWIST_RADAR = 1 << 6, AE_H2_TWIST_CAMO = 1 << 7,
	AE_H2_TWIST_WEAPONS = 1 << 8, AE_H2_TWIST_LOADOUT = 1 << 9, AE_H2_TWIST_BALL_SPEED = 1 << 10,
	AE_H2_TWIST_CRAZY = 1 << 11, AE_H2_TWIST_AT_HOME = 1 << 12, AE_H2_TWIST_SINGLE = 1 << 13, AE_H2_TWIST_ARM = 1 << 14,
	AE_H2_TWIST_RESET = 1 << 15
};

struct ae_h2_preset
{
	char const *stored;      /* the stored name, at most 11 characters */
	char const *display;     /* the display name (empty for a merge) */
	char const *base;        /* the AE seed it keeps the rules of (empty for a merge) */
	char const *style;       /* its placement: AE CASUAL, AE COMP ... */
	char const *group;       /* and group: TEAM ARENA, FREE FOR ALL, ACTION SACK ... */
	unsigned int twist;      /* AE_H2_TWIST_*: the fields below it sets */
	unsigned char engine;    /* AE_H2_ENGINE_* */
	unsigned char teams;
	short score;             /* score to win in the engine's own unit (kills, captures, minutes, juggernaut points) */
	unsigned char lives;     /* 0 unlimited */
	unsigned char respawn_seconds, suicide_seconds, betrayal_seconds;
	unsigned char no_shields, radar, camo;
	unsigned char weapon_set; /* enum game_engine_weapons */
	unsigned char no_map_weapons;
	unsigned char primary, secondary; /* CE loadout weapons (_loadout_weapon_*) */
	unsigned char no_vehicles;
	unsigned char ball_speed; /* oddball: 0 slow, 1 normal, 2 fast */
	unsigned char flag_at_home; /* CTF: your flag at home to score */
	unsigned short single_flag_seconds; /* CTF single flag: seconds before the flag changes sides */
	unsigned char arm_seconds, reset_seconds; /* bomb */
	unsigned char merge;     /* 1: an existing AE seed's settings only (its AE block), no gametype of its own */
	unsigned char spare;
	unsigned char ext[AE_VARIANT_EXT_SIZE];
};

int ae_h2_preset_count(void);
struct ae_h2_preset const *ae_h2_preset_get(int index);
/* a stored name (ASCII, letters' case aside, at most 11 characters read): its index, else -1 */
int ae_h2_preset_find(char const *stored);
/* the same for a wide stored name (a game variant's) */
int ae_h2_preset_find_wide(wchar_t const *stored);
/* the preset's AE block */
void ae_h2_preset_ext(int index, struct ae_variant_ext *ext);

#endif
